head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gSeq;
scwin.gIsurCd;
scwin.gExcptTpCd = '1'; //1=불성실예외법인관리, 2=실질심사대상법인관리

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gParamObj = new Array(2);
scwin.vScrenID = 'ULDSTF37010.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    fn_Search();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    var url = "/UnfaithfulDesignReport.do?method=listUnfaithfulExpt" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&DEP_CD=" + $c.stf.getObjectValue(cmb_TeamList) + "&EMP_NO=" + $c.stf.getObjectValue(cmb_EmpList) + "&STRT_DD=" + $c.stf.getObjectValue(edt_FromDate) + "&END_DD=" + $c.stf.getObjectValue(edt_ToDate) + "&NFAITHDISCLS_EXCPT_TP_CD=" + scwin.gExcptTpCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_List.getCellData(eval(obj), "ACPT_NO");
    scwin.gSeq = dts_List.getCellData(eval(obj), "SEQ");
    scwin.gIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+gAcptNo+","+ gIsurCd);

};
scwin.fn_PopupNew = function() {
    scwin.gAcptNo = '';
    scwin.gSeq = '';
    scwin.gIsurCd = '';
    var gGridNewYn = 'N';
    scwin.fn_PopupDetail(gGridNewYn);
};
scwin.fn_PopupDetail = function(gGridNewYn) {
    //var url = "/dsclmgt/ULDSTF37011.gfm";
    //var winTitle ="불성실공시법인적용예외 보고서";
    //frame.CreateDialogFrame("ULDSTF37011", url , winTitle ,100, -10, 710,  750+30, "window" );
    var url = "/dsclmgt/ULDSTF37011.gfm?";
    //url += "&ACPT_NO=" + gAcptNo;
    url += "&SEQ=" + scwin.gSeq;
    url += "&ISUR_CD=" + scwin.gIsurCd;
    url += "&GRID_NEW_YN=" + gGridNewYn;
    url += "&EXCPT_TP_CD=" + scwin.gExcptTpCd;
    url += "&frameID=" + frame.FrameID;
    if (scwin.fn_setParam(scwin.gSeq, scwin.gIsurCd)) {
        // formal arguments
        $c.frame.path("../../").GWinOpen("ULDSTF37011", url, "불성실예외처리법인관리 상세", 100, -10, 710, 750 + 40, "");
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    var gGridNewYn = 'N';
    if (colid == "PUBL_DDTM") {
        if (scwin.gAcptNo != '') {
            $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
        } else {
            $c.win.alert("해당 공시가 없습니다.");
        }
    } else if (colid == "NFAITH_DESIGN_EXCPT_RSN_NM") {
        scwin.fn_PopupDetail(gGridNewYn);
    } else if (colid == "GRID_NEW_YN") {
        gGridNewYn = 'Y';
        scwin.fn_PopupDetail(gGridNewYn);
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.bnt_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.bnt_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "불성실예외처리법인관리 목록", "", "8");
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_TeamList, js_dep_cd) ;		

};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Input_onclick = function() {
    scwin.fn_PopupNew();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_CheckCond();
};
